    OUT.mkdir(exist_ok=True);(OUT/'motor-options.json').write_text(json.dumps(result,indent=2));(OUT/'motor-options-validation.json').write_text(json.dumps(dict(status='passed',checks=len(checks),items=checks,scope='Arithmetic and balance checks; not vendor thermal qualification, stock verification, new CFD or Lean proof'),indent=2))
