    channels_html=''.join(f'<li><strong>{esc(x["destination"])}:</strong> <a href="{esc(x["url"])}">{esc(x["name"])}</a> · {esc(x["phone"] or "No verified stock contact")}<p>{esc(x["status"])}</p></li>' for x in channels)
